WITH lines AS (SELECT id, service, host, log_ts, attr_key, v FROM app_logs LATERAL VIEW EXPLODE(context) x AS attr_key, v) SELECT DATE_TRUNC('DAY', log_ts) AS activity_day, SORT_ARRAY(COLLECT_SET(host)) AS host_list, COUNT(*) AS cnt, SIZE(COLLECT_SET(host)) AS num_hosts, MIN(log_ts) AS first_seen, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS num_rows FROM lines GROUP BY DATE_TRUNC('DAY', log_ts)
